import java.util.Scanner;

public class Solution {
    static long MOD = 998244353L;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        long l = sc.nextLong();
        long r = sc.nextLong();

        if ((n * m) % 2 == 1) {
            System.out.println(powMod(r - l + 1, n * m));
            return;
        }

        long evenCount = r / 2 - (l - 1) / 2;
        long oddCount = (r - l + 1) - evenCount;

        long result = (powMod(evenCount + oddCount, n * m) + powMod(evenCount - oddCount, n * m)) % MOD;
        result = (result * powMod(2, MOD - 2)) % MOD;

        System.out.println(result);
        sc.close();
    }

    static long powMod(long base, long exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }
}
