#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long powMod(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) {
            res = (res * base) % MOD;
        }
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, l, r;
    cin >> n >> m >> l >> r;

    long long totalCells = n * m;
    if (totalCells % 2 == 1) {
        cout << powMod(r - l + 1, totalCells) << "\n";
        return 0;
    }

    long long evenCount = r / 2 - (l - 1) / 2;
    long long oddCount = (r - l + 1) - evenCount;

    long long result = (powMod(evenCount + oddCount, totalCells) + powMod(evenCount - oddCount, totalCells)) % MOD;
    result = (result * powMod(2, MOD - 2)) % MOD;

    cout << result << "\n";

    return 0;
}
